import{_ as e,c as n,o as r,a3 as l}from"./chunks/framework.BusRvirq.js";const L=JSON.parse('{"title":"SyncLLM 엔터프라이즈 도입 FAQ","description":"SyncLLM 비용 절감 원리, 온프레미스 망분리 배포, PII 개인정보 규제 준수 및 레이턴시 영향 자주 묻는 질문","frontmatter":{"title":"SyncLLM 엔터프라이즈 도입 FAQ","shortTitle":"도입 FAQ","category":"거버넌스 & FAQ","sort":6,"description":"SyncLLM 비용 절감 원리, 온프레미스 망분리 배포, PII 개인정보 규제 준수 및 레이턴시 영향 자주 묻는 질문","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/syncllm/enterprise-faq.html"}]]},"headers":[],"relativePath":"syncllm/enterprise-faq.md","filePath":"ko/syncllm/enterprise-faq.md","lastUpdated":1789435621000}'),t={name:"syncllm/enterprise-faq.md"};function i(s,a,o,c,h,d){return r(),n("div",null,[...a[0]||(a[0]=[l('<h1 id="syncllm-엔터프라이즈-도입-faq" tabindex="-1">SyncLLM 엔터프라이즈 도입 FAQ <a class="header-anchor" href="#syncllm-엔터프라이즈-도입-faq" aria-label="Permalink to “SyncLLM 엔터프라이즈 도입 FAQ”">​</a></h1><h2 id="_1-비용-절감-및-finops-관련" tabindex="-1">1. 비용 절감 및 FinOps 관련 <a class="header-anchor" href="#_1-비용-절감-및-finops-관련" aria-label="Permalink to “1. 비용 절감 및 FinOps 관련”">​</a></h2><h3 id="q1-시맨틱-캐시-semantic-cache-를-도입하면-실제로-비용이-얼마나-절감되나요" tabindex="-1">Q1. 시맨틱 캐시(Semantic Cache)를 도입하면 실제로 비용이 얼마나 절감되나요? <a class="header-anchor" href="#q1-시맨틱-캐시-semantic-cache-를-도입하면-실제로-비용이-얼마나-절감되나요" aria-label="Permalink to “Q1. 시맨틱 캐시(Semantic Cache)를 도입하면 실제로 비용이 얼마나 절감되나요?”">​</a></h3><ul><li><strong>답변</strong>: 엔터프라이즈 사내 챗봇, 지식 검색(RAG), 회귀 테스트(SyncETA) 등 정형화된 요청이 반복되는 환경에서는 <strong>평균 35% ~ 48%의 LLM API 비용 절감</strong>이 실측되었습니다.</li><li>SyncLLM의 시맨틱 캐시는 단순 텍스트 일치가 아니라 임베딩 벡터 코사인 유사도(기본값: 0.92 이상)를 기준으로 판정하므로, 문장 구조나 조사가 약간 달라져도 기존 캐시된 고품질 답변을 즉시 반환합니다.</li></ul><h3 id="q2-예산-한도를-초과하면-서비스가-즉시-중단되나요" tabindex="-1">Q2. 예산 한도를 초과하면 서비스가 즉시 중단되나요? <a class="header-anchor" href="#q2-예산-한도를-초과하면-서비스가-즉시-중단되나요" aria-label="Permalink to “Q2. 예산 한도를 초과하면 서비스가 즉시 중단되나요?”">​</a></h3><ul><li><strong>답변</strong>: 기본 정책은 <code>Soft Limit</code>으로 동작하여 관리자에게 Slack/이메일로 경고 알림을 발송하고, 2차 정책에 따라 저비용 경량 모델(vLLM 사내 로컬 모델 또는 gpt-4o-mini)로 자동 다운그레이드 라우팅하여 비즈니스 연속성을 보장합니다. 명시적으로 <code>hardLimitEnabled: true</code>를 설정한 경우에만 <code>429 Too Many Requests</code>를 반환합니다.</li></ul><hr><h2 id="_2-보안-및-개인정보-pii-관련" tabindex="-1">2. 보안 및 개인정보(PII) 관련 <a class="header-anchor" href="#_2-보안-및-개인정보-pii-관련" aria-label="Permalink to “2. 보안 및 개인정보(PII) 관련”">​</a></h2><h3 id="q3-외부-상용-llm-openai-anthropic-으로-사내-민감-데이터가-유출되지-않나요" tabindex="-1">Q3. 외부 상용 LLM(OpenAI, Anthropic)으로 사내 민감 데이터가 유출되지 않나요? <a class="header-anchor" href="#q3-외부-상용-llm-openai-anthropic-으로-사내-민감-데이터가-유출되지-않나요" aria-label="Permalink to “Q3. 외부 상용 LLM(OpenAI, Anthropic)으로 사내 민감 데이터가 유출되지 않나요?”">​</a></h3><ul><li><strong>답변</strong>: SyncLLM의 인라인 보안 파이프라인이 요청 페이로드를 실시간 가로채어 주민등록번호, 휴대폰 번호, 신용카드 번호, 이메일, API 시크릿 키 등을 자동 감지하고 고유 토큰(<code>&lt;PII_PHONE_1&gt;</code>, <code>&lt;PII_EMAIL_1&gt;</code>)으로 마스킹한 후 외부로 전송합니다.</li><li>외부 모델이 응답을 반환하면 메모리 상의 안전한 매핑 테이블을 통해 원래 데이터로 역마스킹(Unmasking)하여 사용자에게 전달하므로 외부 모델 학습이나 로그에 절대 노출되지 않습니다.</li></ul><hr><h2 id="_3-인프라-및-성능-관련" tabindex="-1">3. 인프라 및 성능 관련 <a class="header-anchor" href="#_3-인프라-및-성능-관련" aria-label="Permalink to “3. 인프라 및 성능 관련”">​</a></h2><h3 id="q4-게이트웨이-추가로-인한-네트워크-레이턴시-latency-오버헤드는-어느-정도인가요" tabindex="-1">Q4. 게이트웨이 추가로 인한 네트워크 레이턴시(Latency) 오버헤드는 어느 정도인가요? <a class="header-anchor" href="#q4-게이트웨이-추가로-인한-네트워크-레이턴시-latency-오버헤드는-어느-정도인가요" aria-label="Permalink to “Q4. 게이트웨이 추가로 인한 네트워크 레이턴시(Latency) 오버헤드는 어느 정도인가요?”">​</a></h3><ul><li><strong>답변</strong>: <ul><li><strong>시맨틱 캐시 히트 시</strong>: 외부 LLM 호출(1,000ms ~ 3,000ms)을 완전히 생략하고 인메모리 Redis에서 즉시 반환하므로 <strong>전체 응답 속도가 15ms 미만</strong>으로 비약적 단축됩니다.</li><li><strong>캐시 미스 시</strong>: 인라인 PII 검사와 라우팅 룰 평가에 소요되는 오버헤드는 <strong>8ms ~ 12ms 수준</strong>으로 인간 사용자가 체감할 수 없는 극소한 수준입니다.</li></ul></li></ul><h3 id="q5-금융-공공-등-완전-망분리-온프레미스-환경에-구축할-수-있나요" tabindex="-1">Q5. 금융/공공 등 완전 망분리 온프레미스 환경에 구축할 수 있나요? <a class="header-anchor" href="#q5-금융-공공-등-완전-망분리-온프레미스-환경에-구축할-수-있나요" aria-label="Permalink to “Q5. 금융/공공 등 완전 망분리 온프레미스 환경에 구축할 수 있나요?”">​</a></h3><ul><li><strong>답변</strong>: 네, 가능합니다. SyncLLM은 Kubernetes Helm 차트 및 공인폐쇄망 Docker 이미지를 제공하며, 외부 인터넷 연결 없이 사내에 구축된 로컬 vLLM, Ollama, SGLang 추론 서버와 연동하여 100% 온프레미스 단독 운영을 지원합니다.</li></ul>',16)])])}const p=e(t,[["render",i]]);export{L as __pageData,p as default};
